alter table public.gather_ingredient_catalog\n  add column if not exists created_by uuid references auth.users(id) on delete set null;\n\ngrant insert, update on public.gather_ingredient_catalog to authenticated;\n\ndrop policy if exists signed_in_insert_own_ingredient_catalog\n  on public.gather_ingredient_catalog;\ncreate policy signed_in_insert_own_ingredient_catalog\n  on public.gather_ingredient_catalog\n  for insert to authenticated\n  with check ((select auth.uid()) = created_by);\n\ndrop policy if exists signed_in_update_own_ingredient_catalog\n  on public.gather_ingredient_catalog;\ncreate policy signed_in_update_own_ingredient_catalog\n  on public.gather_ingredient_catalog\n  for update to authenticated\n  using ((select auth.uid()) = created_by)\n  with check ((select auth.uid()) = created_by);\n